import { basename } from "node:path";
import {
  VERSION,
  type ExtensionAPI,
  type KeybindingsManager,
} from "@earendil-works/pi-coding-agent";

import { CodexEditor, CodexFooter, CodexHeader } from "./components.js";
import { registerCodexTools } from "./tools.js";

export const CODEX_THEME_NAME = "codex-pi";

export default function codexUiExtension(pi: ExtensionAPI): void {
  let currentKeybindings: KeybindingsManager | undefined;
  registerCodexTools(pi, undefined, { getKeybindings: () => currentKeybindings });

  let currentModelId: string | undefined;
  pi.on("model_select", (event) => {
    currentModelId = event.model.id;
  });

  pi.registerMarkdownTransformer((markdown, context) => {
    if (context.messageType !== "user" || markdown.length === 0 || markdown.startsWith("› ")) {
      return markdown;
    }
    return `› ${markdown}`;
  });

  pi.on("session_start", (_event, ctx) => {
    if (ctx.mode !== "tui") return;

    currentModelId = ctx.model?.id;
    if (ctx.ui.theme.name !== CODEX_THEME_NAME) {
      const profileTheme = ctx.ui.getTheme(CODEX_THEME_NAME);
      if (!profileTheme) {
        ctx.ui.notify(`Codex profile theme unavailable: ${CODEX_THEME_NAME}`, "warning");
      } else {
        const themeResult = ctx.ui.setTheme(profileTheme);
        if (!themeResult.success) {
          ctx.ui.notify(`Codex profile theme unavailable: ${themeResult.error ?? "unknown error"}`, "warning");
        }
      }
    }

    const getTheme = () => ctx.ui.theme;
    const getModelId = () => currentModelId;
    const getThinkingLevel = () => pi.getThinkingLevel();

    ctx.ui.setHeader(() => new CodexHeader({
      version: VERSION,
      cwd: ctx.cwd,
      home: process.env.HOME,
      getModelId,
      getThinkingLevel,
      getTheme,
    }));

    ctx.ui.setEditorComponent((tui, editorTheme, keybindings) => {
      currentKeybindings = keybindings;
      return new CodexEditor(tui, editorTheme, keybindings, getTheme);
    });

    ctx.ui.setFooter((_tui, _theme, footerData) => new CodexFooter({
      cwd: ctx.cwd,
      home: process.env.HOME,
      getModelId,
      getThinkingLevel,
      getContextUsage: () => ctx.getContextUsage(),
      getExtensionStatuses: () => footerData.getExtensionStatuses(),
      getTheme,
    }));

    ctx.ui.setTitle(`π · ${basename(ctx.cwd) || "session"}`);
    ctx.ui.setWorkingIndicator({
      frames: [
        ctx.ui.theme.fg("dim", "·"),
        ctx.ui.theme.fg("muted", "•"),
        ctx.ui.theme.fg("accent", "●"),
        ctx.ui.theme.fg("muted", "•"),
      ],
      intervalMs: 120,
    });
  });
}

import { truncateToWidth, visibleWidth } from "@earendil-works/pi-tui";

const BACKGROUND_RESET = "\x1b[49m";
const FULL_SGR_RESET = /\x1b\[(?:0)?m/g;

export interface FitToWidthOptions {
  ellipsis?: string;
  pad?: boolean;
}

export interface PrioritizedSegment {
  text: string;
  priority: number;
}

export interface ContextPercent {
  percent: number | null;
}

export function normalizeWidth(width: number): number {
  if (!Number.isFinite(width)) return 0;
  return Math.max(0, Math.floor(width));
}

export function fitToWidth(
  text: string,
  width: number,
  options: FitToWidthOptions = {},
): string {
  const safeWidth = normalizeWidth(width);
  if (safeWidth === 0) return "";

  const fitted = truncateToWidth(text, safeWidth, options.ellipsis ?? "");
  if (!options.pad) return fitted;

  return `${fitted}${" ".repeat(Math.max(0, safeWidth - visibleWidth(fitted)))}`;
}

export function paintBackground(line: string, width: number, backgroundAnsi: string): string {
  const safeWidth = normalizeWidth(width);
  if (safeWidth === 0) return "";

  const fitted = fitToWidth(line, safeWidth, { pad: true });
  const backgroundSafe = fitted.replace(
    FULL_SGR_RESET,
    (reset) => `${reset}${backgroundAnsi}`,
  );
  return `${backgroundAnsi}${backgroundSafe}${BACKGROUND_RESET}`;
}

export function fitSegments(
  segments: readonly PrioritizedSegment[],
  width: number,
  separator: string,
): string {
  const safeWidth = normalizeWidth(width);
  if (safeWidth === 0) return "";

  const active = segments
    .map((segment, index) => ({ ...segment, index }))
    .filter((segment) => segment.text.length > 0);
  if (active.length === 0) return "";

  const join = () => active
    .sort((left, right) => left.index - right.index)
    .map((segment) => segment.text)
    .join(separator);

  while (active.length > 1 && visibleWidth(join()) > safeWidth) {
    let removableIndex = 0;
    for (let index = 1; index < active.length; index += 1) {
      const candidate = active[index];
      const current = active[removableIndex];
      if (
        candidate.priority < current.priority
        || (candidate.priority === current.priority && candidate.index > current.index)
      ) {
        removableIndex = index;
      }
    }
    active.splice(removableIndex, 1);
  }

  return fitToWidth(join(), safeWidth);
}

export function formatHomePath(path: string, home = process.env.HOME): string {
  if (!home) return path;

  const normalizedHome = home.replace(/[\\/]+$/u, "");
  if (path === normalizedHome) return "~";
  if (
    path.startsWith(`${normalizedHome}/`)
    || path.startsWith(`${normalizedHome}\\`)
  ) {
    return `~${path.slice(normalizedHome.length)}`;
  }
  return path;
}

export function formatContextLeft(usage: ContextPercent | undefined): string | undefined {
  if (!usage || usage.percent === null || !Number.isFinite(usage.percent)) {
    return undefined;
  }

  const left = Math.round(Math.max(0, Math.min(100, 100 - usage.percent)));
  return `Context ${left}% left`;
}

import {
  CustomEditor,
  type ContextUsage,
  type KeybindingsManager,
  type Theme,
} from "@earendil-works/pi-coding-agent";
import {
  stripTerminalSequences,
  visibleWidth,
  type Component,
  type EditorTheme,
  type TUI,
} from "@earendil-works/pi-tui";

import {
  fitSegments,
  fitToWidth,
  formatContextLeft,
  formatHomePath,
  normalizeWidth,
  paintBackground,
  type PrioritizedSegment,
} from "./layout.js";

export interface CodexHeaderOptions {
  version: string;
  cwd: string;
  home?: string;
  getModelId: () => string | undefined;
  getThinkingLevel: () => string;
  getTheme: () => Theme;
}

export interface CodexFooterOptions {
  cwd: string;
  home?: string;
  getModelId: () => string | undefined;
  getThinkingLevel: () => string;
  getContextUsage: () => Pick<ContextUsage, "percent"> | undefined;
  getExtensionStatuses: () => ReadonlyMap<string, string>;
  getTheme: () => Theme;
}

export class CodexHeader implements Component {
  constructor(private readonly options: CodexHeaderOptions) {}

  render(width: number): string[] {
    const safeWidth = normalizeWidth(width);
    if (safeWidth === 0) return [];

    const theme = this.options.getTheme();
    const brand = `${theme.bold(theme.fg("accent", "pi"))}${theme.fg("dim", ` v${this.options.version} · Codex profile`)}`;
    if (safeWidth < 12) {
      return [fitToWidth(brand, safeWidth)];
    }

    const frameWidth = Math.min(safeWidth, 84);
    const innerWidth = frameWidth - 2;
    const border = (text: string) => theme.fg("borderMuted", text);
    const frameLine = (content: string) => (
      `${border("│")}${fitToWidth(content, innerWidth, { pad: true })}${border("│")}`
    );

    const modelId = this.options.getModelId() ?? "No model";
    const thinking = this.options.getThinkingLevel();
    let modelLine = `${theme.fg("dim", "model: ")}${theme.bold(modelId)}${theme.fg("muted", ` · ${thinking}`)}`;
    const modelHint = `${theme.fg("accent", "/model")} ${theme.fg("dim", "to change")}`;
    if (visibleWidth(modelLine) + visibleWidth(modelHint) + 2 <= innerWidth) {
      modelLine += `${" ".repeat(innerWidth - visibleWidth(modelLine) - visibleWidth(modelHint))}${modelHint}`;
    }

    const directory = formatHomePath(this.options.cwd, this.options.home);
    const directoryLine = `${theme.fg("dim", "directory: ")}${theme.bold(directory)}`;

    return [
      border(`┌${"─".repeat(innerWidth)}┐`),
      frameLine(brand),
      frameLine(""),
      frameLine(modelLine),
      frameLine(directoryLine),
      border(`└${"─".repeat(innerWidth)}┘`),
    ];
  }

  invalidate(): void {}
}

export class CodexFooter implements Component {
  constructor(private readonly options: CodexFooterOptions) {}

  render(width: number): string[] {
    const safeWidth = normalizeWidth(width);
    if (safeWidth === 0) return [];

    const theme = this.options.getTheme();
    const modelId = this.options.getModelId() ?? "No model";
    const thinking = this.options.getThinkingLevel();
    const context = formatContextLeft(this.options.getContextUsage());
    const statuses = [...this.options.getExtensionStatuses().values()]
      .map((status) => stripTerminalSequences(status).trim().replace(/^·\s*/u, ""))
      .filter((status) => status.length > 0);

    const segments: PrioritizedSegment[] = [
      {
        text: theme.fg("warning", `${modelId} ${thinking}`),
        priority: 90,
      },
      {
        text: theme.fg("success", formatHomePath(this.options.cwd, this.options.home)),
        priority: 40,
      },
    ];
    if (context) {
      segments.push({ text: theme.fg("warning", context), priority: 60 });
    }
    for (const status of statuses) {
      segments.push({ text: theme.fg("dim", status), priority: 100 });
    }

    const leftPadding = safeWidth > 1 ? " " : "";
    const contentWidth = safeWidth - visibleWidth(leftPadding);
    const separator = theme.fg("dim", " · ");
    const content = fitSegments(segments, contentWidth, separator);
    return [fitToWidth(`${leftPadding}${content}`, safeWidth)];
  }

  invalidate(): void {}
}

const PLACEHOLDER = "Ask Pi to do anything";
const FULL_RESET = "\x1b[0m";

export class CodexEditor extends CustomEditor {
  constructor(
    tui: TUI,
    editorTheme: EditorTheme,
    keybindings: KeybindingsManager,
    private readonly getTheme: () => Theme,
  ) {
    super(tui, editorTheme, keybindings, { paddingX: 1 });
  }

  render(width: number): string[] {
    const safeWidth = normalizeWidth(width);
    if (safeWidth === 0) return [];

    const lines = super.render(safeWidth);
    if (lines.length === 0) return [];

    const theme = this.getTheme();
    const bottomBorderIndex = findBottomBorderIndex(lines, this.isShowingAutocomplete());
    const output = [...lines];
    output[0] = " ".repeat(safeWidth);
    if (bottomBorderIndex !== undefined) {
      output[bottomBorderIndex] = " ".repeat(safeWidth);
    }

    if (output.length > 1 && bottomBorderIndex !== 1) {
      output[1] = addPrompt(
        output[1] ?? "",
        theme,
        this.getText().length === 0,
      );
    }

    const background = theme.getBgAnsi("selectedBg");
    return output.map((line) => paintBackground(line, safeWidth, background));
  }
}

function addPrompt(line: string, theme: Theme, showPlaceholder: boolean): string {
  const prompt = theme.fg("muted", "›");
  let prompted = line.startsWith(" ")
    ? `${prompt}${line.slice(1)}`
    : `${prompt}${line}`;

  if (!showPlaceholder) return prompted;

  const resetIndex = prompted.indexOf(FULL_RESET);
  const placeholder = theme.fg("dim", PLACEHOLDER);
  if (resetIndex === -1) {
    return `${prompted}${placeholder}`;
  }

  const insertionPoint = resetIndex + FULL_RESET.length;
  prompted = `${prompted.slice(0, insertionPoint)}${placeholder}${prompted.slice(insertionPoint)}`;
  return prompted;
}

function findBottomBorderIndex(
  lines: readonly string[],
  autocompleteVisible: boolean,
): number | undefined {
  for (let index = lines.length - 1; index > 0; index -= 1) {
    const plain = stripTerminalSequences(lines[index] ?? "");
    if (/^─+$/u.test(plain) || /^─── [↑↓] \d+ more /u.test(plain)) {
      return index;
    }
  }

  return autocompleteVisible ? undefined : Math.max(1, lines.length - 1);
}

