   133	export class CodexEditor extends CustomEditor {
   134	  constructor(
   135	    tui: TUI,
   136	    editorTheme: EditorTheme,
   137	    keybindings: KeybindingsManager,
   138	    private readonly getTheme: () => Theme,
   139	  ) {
   140	    super(tui, editorTheme, keybindings, { paddingX: 1 });
   141	  }
   142	
   143	  render(width: number): string[] {
   144	    const safeWidth = normalizeWidth(width);
   145	    if (safeWidth === 0) return [];
   146	
   147	    const lines = super.render(safeWidth);
   148	    if (lines.length === 0) return [];
   149	
   150	    const theme = this.getTheme();
   151	    const bottomBorderIndex = findBottomBorderIndex(lines, this.isShowingAutocomplete());
   152	    const output = [...lines];
   153	    output[0] = " ".repeat(safeWidth);
   154	    if (bottomBorderIndex !== undefined) {
   155	      output[bottomBorderIndex] = " ".repeat(safeWidth);
   156	    }
   157	
   158	    if (output.length > 1 && bottomBorderIndex !== 1) {
   159	      output[1] = addPrompt(
   160	        output[1] ?? "",
   161	        theme,
   162	        this.getText().length === 0,
   163	      );
   164	    }
   165	
   166	    const background = theme.getBgAnsi("selectedBg");
   167	    return output.map((line) => paintBackground(line, safeWidth, background));
   168	  }
   169	}
   170	
   171	function addPrompt(line: string, theme: Theme, showPlaceholder: boolean): string {
   172	  const prompt = theme.fg("muted", "›");
   173	  let prompted = line.startsWith(" ")
   174	    ? `${prompt}${line.slice(1)}`
   175	    : `${prompt}${line}`;
   176	
   177	  if (!showPlaceholder) return prompted;
   178	
   179	  const resetIndex = prompted.indexOf(FULL_RESET);
   180	  const placeholder = theme.fg("dim", PLACEHOLDER);
   181	  if (resetIndex === -1) {
   182	    return `${prompted}${placeholder}`;
   183	  }
   184	
   185	  const insertionPoint = resetIndex + FULL_RESET.length;
   186	  prompted = `${prompted.slice(0, insertionPoint)}${placeholder}${prompted.slice(insertionPoint)}`;
   187	  return prompted;
   188	}
   189	
   190	function findBottomBorderIndex(
   191	  lines: readonly string[],
   192	  autocompleteVisible: boolean,
   193	): number | undefined {
   194	  for (let index = lines.length - 1; index > 0; index -= 1) {
   195	    const plain = stripTerminalSequences(lines[index] ?? "");
   196	    if (/^─+$/u.test(plain) || /^─── [↑↓] \d+ more /u.test(plain)) {
   197	      return index;
   198	    }
   199	  }
   200	
   201	  return autocompleteVisible ? undefined : Math.max(1, lines.length - 1);
   202	}

