464	function updateBashLifecycle(
465	  state: CodexBashState,
466	  context: {
467	    executionStarted: boolean;
468	    isPartial: boolean;
469	    isError: boolean;
470	    invalidate(): void;
471	  },
472	): void {
473	  const nextStatus: CodexBashStatus = context.isError
474	    ? "failed"
475	    : !context.isPartial
476	      ? "completed"
477	      : context.executionStarted
478	        ? "running"
479	        : "pending";
480	
481	  if (nextStatus === "running") {
482	    if (state.startedAt === undefined) {
483	      state.startedAt = Date.now();
484	      state.endedAt = undefined;
485	    }
486	    if (state.interval === undefined) {
487	      state.interval = setInterval(() => context.invalidate(), BASH_DURATION_REFRESH_MS);
488	    }
489	  } else if (nextStatus === "completed" || nextStatus === "failed") {
490	    if (state.startedAt !== undefined && state.endedAt === undefined) {
491	      state.endedAt = Date.now();
492	    }
493	    if (state.interval !== undefined) {
494	      clearInterval(state.interval);
495	      state.interval = undefined;
496	    }
497	  }
498	
499	  state.status = nextStatus;
500	}
